VALUES ('aceh-pintu-seulanga', 'Pintu Seulanga Aceh', 'Adat', 'Aceh', 'sage', 'Aceh', 'Ukiran pintu Aceh bermotif bunga seulanga, kubah masjid raya, dan lentera — kemegahan Serambi Mekkah dalam hijau-emas.', '["Pintu Aceh", "Islami", "Lentera Bergoyang", "Provinsi Aceh"]'::jsonb, 'Baru', 'bingkai', 'none', 'cinzel', '{"bg": "#fbf7ec", "card": "#fefcf8", "primary": "#1f4d2b", "on-primary": "#ffffff", "gold": "#d4a52c", "gold-deep": "#7f621b", "ink": "#0e2313", "muted": "#636e60"}'::jsonb, FALSE, 300, 'great-vibes', '/img/tema/provinsi/aceh-pintu-seulanga-latar.svg', '', '/img/tema/provinsi/aceh-pintu-seulanga-hiasan.svg', 'kilau-emas', 'prov-aceh-pintu-seulanga', 'satu', 'keraton', '/img/tema/provinsi/aceh-pintu-seulanga-motif.svg', 'pola', 'zoom-masuk', 'zoom-masuk', TRUE, TRUE)
